import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import * as api from './api'
// Generated by the backend tests (backend/tests/test_contracts.py): the exact shapes the API returns.
import storageRaw from '../../contracts/session_storage.json?raw'
import summaryRaw from '../../contracts/session_summary.json?raw'
import reportRaw from '../../contracts/session_validation_report.json?raw'
import RecorderPanel from './RecorderPanel'

vi.mock('./api')

afterEach(cleanup)

const summary = JSON.parse(summaryRaw) as api.SessionSummary
const storage = JSON.parse(storageRaw) as api.SessionStorage
const report = JSON.parse(reportRaw) as api.ValidationReport

function panel() {
  return <RecorderPanel recording={null} recordingStopped={null} replay={null} />
}

describe('backend contract fixtures through the Sessions panel', () => {
  it('renders the session summary (name, endedAt null, incomplete) and the storage line', async () => {
    vi.mocked(api.fetchSessions).mockResolvedValue([summary])
    vi.mocked(api.fetchSessionStorage).mockResolvedValue(storage)
    render(panel())
    expect(await screen.findByText(summary.sessionId)).toBeTruthy()
    expect(screen.getByText('INCOMPLETE')).toBeTruthy()
    expect(screen.getByRole('button', { name: `Validate session ${summary.sessionId}` })).toBeTruthy()
    expect(await screen.findByText('Storage: 0.0 MB · no size limit · keeps 30 days')).toBeTruthy()
  })

  it('renders the validation report: counts, rule badges, truncation note, numeric t', async () => {
    vi.mocked(api.fetchSessions).mockResolvedValue([summary])
    vi.mocked(api.fetchSessionStorage).mockResolvedValue(storage)
    vi.mocked(api.validateSession).mockResolvedValue(report)
    expect(typeof report.issues[0].t).toBe('number')
    render(panel())
    fireEvent.click(await screen.findByRole('button', { name: `Validate session ${summary.sessionId}` }))
    expect(await screen.findByText(`${report.checked} messages checked, ${report.withIssues} with issues`)).toBeTruthy()
    for (const rule of report.byRule) {
      expect(screen.getByText(rule.rule)).toBeTruthy()
      expect(screen.getByText(rule.severity).className).toContain(rule.severity === 'error' ? 'down' : 'warn')
    }
    expect(screen.getByText(/the report lists the first 100 issues/)).toBeTruthy()
    expect(screen.getByText(new RegExp(`line ${report.issues[0].line} · ${report.issues[0].topic}`))).toBeTruthy()
  })
})
